import React, { useEffect, useState } from "react";
import {
  View, Text, StyleSheet, TextInput, TouchableOpacity,
  ScrollView, Alert, SafeAreaView, KeyboardAvoidingView,
  Platform, StatusBar, ActivityIndicator
} from "react-native";
import axios from "axios";
import { useRouter } from "expo-router";
import { Feather } from "@expo/vector-icons";
import AsyncStorage from "@react-native-async-storage/async-storage";

const COLORS = {
  dark: "#0a3d2e",    // Verde Glaze
  accent: "#1f6f54",  
  silver: "#94a3b8",  
  bg: "#ffffff",      
  border: "#f1f5f9",  
  textLight: "#64748b"
};

export default function Perfil() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [cargandoDatos, setCargandoDatos] = useState(true);
  
  const [usuario, setUsuario] = useState({
    id_usuario: null,
    nombre_completo: "",
    correo: "",
    celular: "",
    direccion: ""
  });

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    try {
      const usuarioRaw = await AsyncStorage.getItem("usuario");
      if (!usuarioRaw) return router.replace("/login");
      
      const user = JSON.parse(usuarioRaw);
      const res = await axios.get(`http://192.168.1.9:3000/api/usuarios/${user.id_usuario}`);
      
      setUsuario({
        id_usuario: res.data.id_usuario,
        nombre_completo: res.data.nombre_completo || "",
        correo: res.data.correo || "",
        celular: res.data.celular || "",
        direccion: res.data.direccion || ""
      });
    } catch (error) {
      console.error("Error al cargar:", error);
    } finally {
      setCargandoDatos(false);
    }
  };

  const guardarCambios = async () => {
    if (!usuario.id_usuario) return;

    try {
      setLoading(true);
      const payload = {
        correo: usuario.correo.trim(),
        celular: String(usuario.celular).trim(),
        direccion: usuario.direccion ? usuario.direccion.trim() : ""
      };

      await axios.put(
        `http://192.168.1.9:3000/api/usuarios/actualizar/${usuario.id_usuario}`, 
        payload
      );
      
      Alert.alert("Glaze", "Información del titular actualizada.");
    } catch (error) {
      console.log("Error 400:", error.response?.data);
      Alert.alert("Error", "No se pudieron guardar los cambios.");
    } finally {
      setLoading(false);
    }
  };

  if (cargandoDatos) return <View style={styles.center}><ActivityIndicator color={COLORS.dark} /></View>;

  return (
    <SafeAreaView style={styles.mainWrapper}>
      <StatusBar barStyle="dark-content" />
      
      <KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={{ flex: 1 }}>
        <ScrollView style={styles.container} showsVerticalScrollIndicator={false}>
          
          <View style={styles.headerTitleContainer}>
            <Text style={styles.headerLabel}>INFORMACIÓN DEL TITULAR</Text>
          </View>

          {/* CAMPO: NOMBRE (NO EDITABLE) */}
          <View style={styles.inputGroup}>
            <Text style={styles.fieldLabel}>NOMBRE COMPLETO (NO EDITABLE)</Text>
            <TextInput 
              style={[styles.input, styles.inputDisabled]} 
              value={usuario.nombre_completo.toUpperCase()} 
              editable={false} 
            />
          </View>

          {/* CAMPO: CORREO */}
          <View style={styles.inputGroup}>
            <Text style={styles.fieldLabel}>CORREO ELECTRÓNICO</Text>
            <TextInput 
              style={styles.input} 
              value={usuario.correo} 
              onChangeText={(t) => setUsuario({...usuario, correo: t})}
              autoCapitalize="none"
            />
          </View>

          {/* CAMPO: CELULAR */}
          <View style={styles.inputGroup}>
            <Text style={styles.fieldLabel}>TELÉFONO DE CONTACTO</Text>
            <TextInput 
              style={styles.input} 
              value={usuario.celular} 
              onChangeText={(t) => setUsuario({...usuario, celular: t})}
              keyboardType="numeric"
            />
          </View>

          {/* NUEVO CAMPO: DIRECCIÓN */}
          <View style={styles.inputGroup}>
            <Text style={styles.fieldLabel}>DIRECCIÓN DE DOMICILIO</Text>
            <TextInput 
              style={styles.input} 
              value={usuario.direccion} 
              onChangeText={(t) => setUsuario({...usuario, direccion: t})}
              placeholder="Ej: Calle 10 # 5-20"
              placeholderTextColor={COLORS.silver}
            />
          </View>

          {/* BOTÓN ESTILO GLAZE */}
          <TouchableOpacity 
            style={styles.btnGuardar} 
            onPress={guardarCambios} 
            disabled={loading}
          >
            {loading ? (
              <ActivityIndicator color="white" />
            ) : (
              <Text style={styles.btnText}>GUARDAR CAMBIOS</Text>
            )}
          </TouchableOpacity>

        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  mainWrapper: { flex: 1, backgroundColor: COLORS.bg },
  center: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  container: { padding: 25 },
  headerTitleContainer: { marginBottom: 30, marginTop: 10 },
  headerLabel: { 
    fontSize: 10, 
    fontWeight: "900", 
    color: COLORS.dark, 
    letterSpacing: 1.5 
  },
  inputGroup: { marginBottom: 25 },
  fieldLabel: { 
    fontSize: 8, 
    fontWeight: "800", 
    color: COLORS.silver, 
    marginBottom: 8,
    letterSpacing: 0.5
  },
  input: { 
    borderBottomWidth: 1, 
    borderBottomColor: "#f0f0f0", 
    paddingVertical: 10, 
    fontSize: 15, 
    color: "#334155" 
  },
  inputDisabled: { 
    color: COLORS.silver, 
    borderBottomColor: "transparent" 
  },
  btnGuardar: { 
    backgroundColor: COLORS.dark, 
    height: 55, 
    alignItems: 'center', 
    justifyContent: 'center', 
    marginTop: 20,
    borderRadius: 2
  },
  btnText: { 
    color: "white", 
    fontSize: 11, 
    fontWeight: "800", 
    letterSpacing: 2 
  }
});
